const userMethods = {
  greet() {
    return `Hi ${this.name}`;
  },
};

function createUser(name) {
  const user = Object.create(userMethods);
  user.name = name;
  return user;
}

const kakade = createUser('Kakade');
console.log(kakade.greet());
console.log(Object.hasOwn(kakade, 'greet'));

questions.question:
What does this print, and why is `spread` different from `child`?

```javascript
const parent = { greet() { return 'hi'; } };
const child = Object.create(parent);
const spread = { ...child };
console.log(child.greet());
console.log(spread.greet);
```

What is logged here, and why?

```javascript
function User() {}
User.prototype.greet = () => 'hi';
const kakade = new User();
User.prototype = { hello: () => 'hello' };
console.log(kakade instanceof User);
console.log(typeof kakade.hello);
